#include <vector>
#include <algorithm>

class Solution {
public:
    int longestSubsequence(std::vector<int>& nums) {
        int ans = 0;
        for (int b = 0; b < 31; ++b) {
            std::vector<int> tails;
            for (int x : nums) {
                if ((x >> b) & 1) {
                    auto it = std::lower_bound(tails.begin(), tails.end(), x);
                    if (it == tails.end()) tails.push_back(x);
                    else *it = x;
                }
            }
            ans = std::max(ans, (int)tails.size());
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int longestSubsequence(int[] nums) {
        int ans = 0;
        for (int b = 0; b < 31; b++) {
            List<Integer> tails = new ArrayList<>();
            for (int x : nums) {
                if (((x >> b) & 1) == 1) {
                    int idx = Collections.binarySearch(tails, x);
                    if (idx < 0) idx = -(idx + 1);
                    if (idx == tails.size()) tails.add(x);
                    else tails.set(idx, x);
                }
            }
            ans = Math.max(ans, tails.size());
        }
        return ans;
    }
}

function longestSubsequence(nums) {
    let ans = 0;
    for (let b = 0; b < 31; b++) {
        const tails = [];
        for (const x of nums) {
            if ((x >> b) & 1) {
                let l = 0, r = tails.length;
                while (l < r) {
                    const mid = (l + r) >> 1;
                    if (tails[mid] < x) l = mid + 1;
                    else r = mid;
                }
                if (l === tails.length) tails.push(x);
                else tails[l] = x;
            }
        }
        ans = Math.max(ans, tails.length);
    }
    return ans;
}
